// Classify the intent of the story reply
const reply = $input.first().json.body.text || '';
const replyLower = reply.toLowerCase();

let intent = 'neutral';
let priority = 'low';

// High intent indicators
if (replyLower.match(/how (much|do i|can i)|interested|sign me up|tell me more|let'?s do this|how does (this|it) work/)) {
  intent = 'buying_signal';
  priority = 'high';
} else if (replyLower.match(/love (this|that|it)|so good|amazing|genius|💯|🔥/)) {
  intent = 'supportive';
  priority = 'medium';
} else if (replyLower.match(/scam|fake|bs|too good to be true|not buying it/)) {
  intent = 'skeptical';
  priority = 'medium';
} else if (replyLower.match(/question|wondering|curious|what about/)) {
  intent = 'curious';
  priority = 'medium';
}

return [{
  json: {
    reply_text: reply,
    username: $input.first().json.body.username,
    story_id: $input.first().json.body.story_id,
    intent,
    priority
  }
}];

